"""Combine the two component JSON values under the business contract in TASK.md."""
import json
from itertools import permutations


def _build_evidence(payload):
    """Return dict[(student, buyer)] -> confidence, and set of sources."""
    best = {}
    for source, student, buyer, strength in payload["evidence"]:
        key = (student, buyer)
        if key not in best:
            best[key] = {}
        if source not in best[key] or strength > best[key][source]:
            best[key][source] = strength
    conf = {k: sum(v.values()) for k, v in best.items()}
    return conf


def _solve(payload, left, right, conf):
    """Solve one drop scenario. Returns result dict or None."""
    students = payload["students"]
    buyers = payload["buyers"]
    n = len(students)

    # Build bipartite graph of usable edges (confidence > 0).
    # Decompose into connected components.
    adj_s = {s: set() for s in students}
    adj_b = {b: set() for b in buyers}
    for (s, b), c in conf.items():
        if c > 0:
            adj_s[s].add(b)
            adj_b[b].add(s)

    # Find connected components.
    seen_s = set()
    seen_b = set()
    components = []
    for s in students:
        if s in seen_s:
            continue
        # BFS over bipartite graph.
        comp_s = set()
        comp_b = set()
        stack = [("s", s)]
        seen_s.add(s)
        while stack:
            kind, node = stack.pop()
            if kind == "s":
                comp_s.add(node)
                for b in adj_s[node]:
                    if b not in seen_b:
                        seen_b.add(b)
                        stack.append(("b", b))
            else:
                comp_b.add(node)
                for s2 in adj_b[node]:
                    if s2 not in seen_s:
                        seen_s.add(s2)
                        stack.append(("s", s2))
        components.append((sorted(comp_s), sorted(comp_b)))

    # Students/buyers with no evidence edges are isolated; they cannot be matched.
    # A full perfect matching requires every student and buyer to be matched.
    # Check feasibility: each component must have equal sides and a perfect matching.
    # Also isolated vertices (no edges) make it infeasible unless both sides empty.
    for comp_s, comp_b in components:
        if len(comp_s) != len(comp_b):
            return None

    # Check all students and buyers are covered by components.
    covered_s = set()
    covered_b = set()
    for comp_s, comp_b in components:
        covered_s.update(comp_s)
        covered_b.update(comp_b)
    if covered_s != set(students) or covered_b != set(buyers):
        return None

    # For each component, enumerate all perfect matchings (bijections).
    # Each component has at most 14 vertices per side.
    comp_matchings = []
    for comp_s, comp_b in components:
        k = len(comp_s)
        matchings = []
        # Enumerate permutations of buyers for this component's students.
        for perm in permutations(comp_b):
            ok = True
            for s, b in zip(comp_s, perm):
                if conf.get((s, b), 0) <= 0:
                    ok = False
                    break
            if ok:
                matchings.append(list(zip(comp_s, perm)))
        if not matchings:
            return None
        comp_matchings.append(matchings)

    # Combine across components (cartesian product).
    all_matchings = [[]]
    for matchings in comp_matchings:
        new = []
        for prefix in all_matchings:
            for m in matchings:
                new.append(prefix + m)
        all_matchings = new

    # Compute floor and total for each matching.
    best_floor = -1
    best_total = -1
    optimal = []
    for matching in all_matchings:
        confs = [conf[(s, b)] for s, b in matching]
        floor = min(confs)
        total = sum(confs)
        if floor > best_floor or (floor == best_floor and total > best_total):
            best_floor = floor
            best_total = total
            optimal = [matching]
        elif floor == best_floor and total == best_total:
            optimal.append(matching)

    count = len(optimal)

    # Compute X and Y.
    X = {s: left[s] for s in students}
    Y = {b: right[b] for b in buyers}

    sumX = sum(X[s] for s in students)
    sumY = sum(Y[b] for b in buyers)

    # For each optimal matching, compute numerator.
    nums = []
    for matching in optimal:
        sxy = sum(X[s] * Y[b] for s, b in matching)
        num = n * sxy - sumX * sumY
        nums.append(num)

    min_num = min(nums)
    max_num = max(nums)

    # Lexicographically smallest buyer vector (by student ID ascending).
    def buyer_vector(matching):
        m = dict(matching)
        return [m[s] for s in students]

    min_vec = None
    max_vec = None
    for matching, num in zip(optimal, nums):
        vec = buyer_vector(matching)
        if num == min_num and (min_vec is None or vec < min_vec):
            min_vec = vec
        if num == max_num and (max_vec is None or vec < max_vec):
            max_vec = vec

    # Forced pairs: pairs present in all optimal matchings.
    forced = []
    for s in students:
        buyers_set = set()
        for matching in optimal:
            m = dict(matching)
            buyers_set.add(m[s])
        if len(buyers_set) == 1:
            forced.append([s, buyers_set.pop()])
    forced.sort(key=lambda p: p[0])

    return {
        "floor": best_floor,
        "total": best_total,
        "count": count,
        "min_num": min_num,
        "max_num": max_num,
        "min_buyers": min_vec,
        "max_buyers": max_vec,
        "forced": forced,
    }


def combine(payload, left, right):
    """Combine the two component JSON values under the business contract in TASK.md."""
    conf = _build_evidence(payload)
    results = []
    for drop in payload["drop"]:
        if drop is None:
            c = conf
        else:
            c = {}
            for (s, b), v in conf.items():
                # Recompute without the dropped source.
                pass
            # Rebuild evidence excluding the dropped source.
            best = {}
            for source, student, buyer, strength in payload["evidence"]:
                if source == drop:
                    continue
                key = (student, buyer)
                if key not in best:
                    best[key] = {}
                if source not in best[key] or strength > best[key][source]:
                    best[key][source] = strength
            c = {k: sum(v.values()) for k, v in best.items()}
        result = _solve(payload, left, right, c)
        results.append({"drop": drop, "result": result})
    return results

