        if key not in best:
            best[key] = {}
        if source not in best[key] or strength > best[key][source]:
            best[key][source] = strength
    conf = {k: sum(v.values()) for k, v in best.items()}
    return conf


def _solve(payload, left, right, conf):
    """Solve one drop scenario. Returns result dict or None."""
    students = payload["students"]
    buyers = payload["buyers"]
    n = len(students)

    # Build bipartite graph of usable edges (confidence > 0).
    # Decompose into connected components.
    adj_s = {s: set() for s in students}
    adj_b = {b: set() for b in buyers}
    for (s, b), c in conf.items():
        if c > 0:
            adj_s[s].add(b)
            adj_b[b].add(s)

    # Find connected components.
    seen_s = set()
    seen_b = set()
    components = []
    for s in students:
        if s in seen_s:
            continue
        # BFS over bipartite graph.
        comp_s = set()
        comp_b = set()
        stack = [("s", s)]
        seen_s.add(s)
        while stack:
            kind, node = stack.pop()
            if kind == "s":
                comp_s.add(node)
                for b in adj_s[node]:
                    if b not in seen_b:
                        seen_b.add(b)
                        stack.append(("b", b))
            else:
                comp_b.add(node)
                for s2 in adj_b[node]:
                    if s2 not in seen_s:
                        seen_s.add(s2)
                        stack.append(("s", s2))
        components.append((sorted(comp_s), sorted(comp_b)))

    # Students/buyers with no evidence edges are isolated; they cannot be matched.
    # A full perfect matching requires every student and buyer to be matched.
    # Check feasibility: each component must have equal sides and a perfect matching.
    # Also isolated vertices (no edges) make it infeasible unless both sides empty.
    for comp_s, comp_b in components:
        if len(comp_s) != len(comp_b):
            return None

    # Check all students and buyers are covered by components.
    covered_s = set()
    covered_b = set()
    for comp_s, comp_b in components:
        covered_s.update(comp_s)
        covered_b.update(comp_b)
    if covered_s != set(students) or covered_b != set(buyers):
        return None

    # For each component, enumerate all perfect matchings (bijections).
    # Each component has at most 14 vertices per side.
    comp_matchings = []
    for comp_s, comp_b in components:
        k = len(comp_s)
        matchings = []
        # Enumerate permutations of buyers for this component's students.
        for perm in permutations(comp_b):
